rows={v['group_id']:v for v in s['files']};O=R/'workspace/local-sr/field-sr002';O.mkdir(parents=True,exist_ok=False);models=json.loads((R/'workspace/local-sr/models/models.json').read_text('utf8'))['records'];choices=[('wdn','realesr-general-wdn-x4v3.pth'),('photo','RealESRGAN_x4plus.pth')]
rep={'schema':'brs-field-local-sr/v2','batch':'FIELD-SR-002','source_review':str(sfile),'source_review_sha256':sha(sfile),'unique_originals':len(ids),'actual_local_rgb_inference_passes':0,'external_calls':0,'image_upload':False,'native_neural_scale':4,'final_scale':8,'post_scale':'Lanczos2x','device':torch.cuda.get_device_name(0),'torch':torch.__version__,'files':[],'pages':[],'runtime_verified':False,'release_eligible':False}
for tag,name in choices:
 rec=next(m for m in models if m['name']==name);model=load_model(Path(rec['path']),rec['sha256'])
 for gid in ids:
  start=time.monotonic();v=rows[gid];src=Image.open(v['source']).convert('RGBA');assert src.getchannel('A').getextrema()==(255,255);sigma=.35 if v['classification']=='opaque_material' else .25
  inp=src.convert('RGB').filter(ImageFilter.GaussianBlur(sigma));ip=O/f'{gid}-{tag}-input.png';inp.save(ip);native=infer_rgb(model,inp);npth=O/f'{gid}-{tag}-native4x.png';native.save(npth);out=native.resize((src.width*8,src.height*8),Image.Resampling.LANCZOS).convert('RGBA');op=O/f'{gid}-{tag}-8x.png';out.save(op)
  rep['files'].append({**{k:v[k] for k in ['group_id','representative','source','source_ptm','source_ptm_sha256','source_rgba_sha256','classification']},'id':gid+'-'+tag,'model':rec,'input':str(ip),'input_sha256':sha(ip),'input_gaussian_sigma_source_px':sigma,'native':str(npth),'native_sha256':sha(npth),'output':str(op),'output_sha256':sha(op),'output_size':list(out.size),'alpha':'opaque255','actual_local_rgb_inference_passes':1,'source_scale_metrics':roundtrip_metrics(src,out),'seconds':time.monotonic()-start,'visual_review':'pending','runtime_verified':False,'release_eligible':False});rep['actual_local_rgb_inference_passes']+=1;save(Q,rep)
